INSERT INTO `movie` (`movie_id`, `movie_name`, `movie_alias`, `actors`, `cover`, `directors`, `douban_score`, `douban_votes`, `type`, `imdb_id`, `languages`, `minutes`, `official_site`, `regions`, `release_date`, `description`, `tags`, `year`, `actor_ids`, `director_ids`) VALUES (26413438, '致命魔术', '魔术师 / The Prestige', '休·杰克曼/克里斯蒂安·贝尔/大卫·鲍伊/迈克尔·凯恩/斯嘉丽·约翰逊', '致命魔术.png', '克里斯托弗·诺兰', 8.9, 856234, '剧情/悬疑/科幻', 'tt0482571', '英语', 130, '', '美国 / 英国', '2006-11-10', '两位魔术师（休·杰克曼、克里斯蒂安·贝尔）为了成为世界最伟大的魔术师，开始了一场你死我活的竞争，执念与谎言将他们带向了悲剧的终局。', '悬疑/诺兰/魔术/经典/美国/2006/烧脑/反转', 2006, '休·杰克曼:1013157|克里斯蒂安·贝尔:1017982|大卫·鲍伊:1000060|迈克尔·凯恩:1003169', '克里斯托弗·诺兰:1054524');
