INSERT INTO `movie` (`movie_id`, `movie_name`, `movie_alias`, `actors`, `cover`, `directors`, `douban_score`, `douban_votes`, `type`, `imdb_id`, `languages`, `minutes`, `official_site`, `regions`, `release_date`, `description`, `tags`, `year`, `actor_ids`, `director_ids`) VALUES (26798603, '少年的你', '少年的你，如此美丽 / Better Days', '易烊千玺/周冬雨/尹昉/黄觉/吴越', '少年的你.png', '曾国祥', 8.3, 916782, '剧情/爱情/犯罪', 'tt9586048', '汉语普通话 / 粤语', 135, '', '中国大陆 / 中国香港', '2019-10-25', '高考前夕，遭受校园霸凌的陈念（周冬雨）在街头意外结识了\"小混混\"小北（易烊千玺），两人在彼此的陪伴下走过了最艰难的时光。', '青春/校园霸凌/2019/中国/剧情/爱情/易烊千玺/周冬雨', 2019, '易烊千玺:1389531|周冬雨:1230175|尹昉:1389532|黄觉:1045752', '曾国祥:1120093');
