INSERT INTO `movie` (`movie_id`, `movie_name`, `movie_alias`, `actors`, `cover`, `directors`, `douban_score`, `douban_votes`, `type`, `imdb_id`, `languages`, `minutes`, `official_site`, `regions`, `release_date`, `description`, `tags`, `year`, `actor_ids`, `director_ids`) VALUES (26897815, '我的姐姐', '我的姐姐 / Sister', '张子枫/肖央/朱媛媛/段博文', '我的姐姐.png', '殷若昕', 7.2, 518764, '剧情/家庭', 'tt14260154', '汉语普通话', 102, '', '中国大陆', '2021-04-02', '父母意外离世后，一心想去北京读研的安然（张子枫）面临着是否抚养弟弟的艰难抉择，在传统观念与个人梦想之间挣扎。', '家庭/亲情/2021/中国/剧情/女性/现实/感动', 2021, '张子枫:1264512|肖央:1107413|朱媛媛:1035614|段博文:1170398', '殷若昕:1389585');
