INSERT INTO `movie` (`movie_id`, `movie_name`, `movie_alias`, `actors`, `cover`, `directors`, `douban_score`, `douban_votes`, `type`, `imdb_id`, `languages`, `minutes`, `official_site`, `regions`, `release_date`, `description`, `tags`, `year`, `actor_ids`, `director_ids`) VALUES (34780988, '流浪地球', '流浪地球 / The Wandering Earth', '吴京/屈楚萧/李光洁/吴孟达/赵今麦/隋磊', '流浪地球.png', '郭帆', 7.9, 1068234, '剧情/科幻/冒险/灾难', 'tt7605074', '汉语普通话 / 英语 / 俄语', 125, '', '中国大陆', '2019-02-05', '太阳急速老化膨胀，地球即将被吞噬。人类开动一万台行星发动机，推动地球逃离太阳系，寻找新的家园。', '科幻/中国/太空/2019/灾难/硬科幻/吴京/春节', 2019, '吴京:1169734|屈楚萧:1389541|李光洁:1084726|吴孟达:1029890|赵今麦:1389542', '郭帆:1358222');
