INSERT INTO `movie` (`movie_id`, `movie_name`, `movie_alias`, `actors`, `cover`, `directors`, `douban_score`, `douban_votes`, `type`, `imdb_id`, `languages`, `minutes`, `official_site`, `regions`, `release_date`, `description`, `tags`, `year`, `actor_ids`, `director_ids`) VALUES (35217145, '奥本海默', '奥本海默 / Oppenheimer', '基里安·墨菲/艾米莉·布朗特/马特·达蒙/小罗伯特·唐尼/弗洛伦斯·皮尤/乔什·哈内特/肯尼斯·布拉纳', '奥本海默.png', '克里斯托弗·诺兰', 8.8, 751263, '剧情/历史/传记', 'tt15398776', '英语 / 德语 / 荷兰语', 180, 'https://www.oppenheimermovie.com', '美国 / 英国', '2023-08-30', '美国\"原子弹之父\"罗伯特·奥本海默（基里安·墨菲）领导曼哈顿计划，开发出改变世界的核武器，之后却在政治漩涡中遭受审判。', '传记/历史/战争/诺兰/2023/美国/科学家/冷战', 2023, '基里安·墨菲:1003745|艾米莉·布朗特:1049534|马特·达蒙:1019766|小罗伯特·唐尼:1023632', '克里斯托弗·诺兰:1054524');
INSERT INTO `movie` (`movie_id`, `movie_name`, `movie_alias`, `actors`, `cover`, `directors`, `douban_score`, `douban_votes`, `type`, `imdb_id`, `languages`, `minutes`, `official_site`, `regions`, `release_date`, `description`, `tags`, `year`, `actor_ids`, `director_ids`) VALUES (35267208, '流浪地球2', '流浪地球2：重启计划 / The Wandering Earth 2', '吴京/刘德华/李雪健/沙溢/宁理/王智/朱颜曼滋/安地', '流浪地球2.png', '郭帆', 8.3, 1326548, '科幻/动作/冒险', 'tt13539646', '汉语普通话', 173, 'https://wanderingearth.movie', '中国大陆', '2023-01-22', '太阳即将毁灭，人类在地球表面建造了巨大的推进器，寻找新家园。然而宇宙之路危机四伏，人类文明的火种能否延续？', '科幻/中国/太空/灾难/特效/硬科幻/2023/中国电影', 2023, '吴京:1169734|刘德华:1027440|李雪健:1029652|沙溢:1039218|宁理:1318627|王智:1274040', '郭帆:1358222');
INSERT INTO `movie` (`movie_id`, `movie_name`, `movie_alias`, `actors`, `cover`, `directors`, `douban_score`, `douban_votes`, `type`, `imdb_id`, `languages`, `minutes`, `official_site`, `regions`, `release_date`, `description`, `tags`, `year`, `actor_ids`, `director_ids`) VALUES (35469584, '宇宙探索编辑部', '宇宙探索编辑部 / Journey to the West', '杨皓宇/艾丽娅/王一通/刘哲铭', '宇宙探索编辑部.png', '孔大山', 8, 356782, '剧情/喜剧/科幻', 'tt19505892', '汉语普通话', 116, '', '中国大陆', '2023-04-01', '一本濒临倒闭的UFO杂志主编（杨皓宇），带着一群信徒踏上了寻找宇宙文明的奇幻公路旅程，荒诞中透着真实的人文关怀。', '喜剧/科幻/2023/中国/独立电影/文艺/公路/UFO', 2023, '杨皓宇:1046987|艾丽娅:1389617|王一通:1389618', '孔大山:1389619');
INSERT INTO `movie` (`movie_id`, `movie_name`, `movie_alias`, `actors`, `cover`, `directors`, `douban_score`, `douban_votes`, `type`, `imdb_id`, `languages`, `minutes`, `official_site`, `regions`, `release_date`, `description`, `tags`, `year`, `actor_ids`, `director_ids`) VALUES (35575063, '年会不能停！', '年会不能停！ / YOLO', '大鹏/白客/任素汐/庄达菲/孙艺洲', '年会不能停！.png', '董润年', 8, 623451, '喜剧', 'tt29065049', '汉语普通话', 127, '', '中国大陆', '2023-12-29', '工厂工人胡建林（大鹏）因为一个误会被调往北京总部，在职场中经历了各种荒诞的年会筹备事件，映射出当代职场众生相。', '喜剧/职场/2023/中国/年会/大鹏/讽刺/轻松', 2023, '大鹏:1205037|白客:1282943|任素汐:1252388|庄达菲:1389568', '董润年:1167458');
INSERT INTO `movie` (`movie_id`, `movie_name`, `movie_alias`, `actors`, `cover`, `directors`, `douban_score`, `douban_votes`, `type`, `imdb_id`, `languages`, `minutes`, `official_site`, `regions`, `release_date`, `description`, `tags`, `year`, `actor_ids`, `director_ids`) VALUES (35709800, '抓娃娃', '抓娃娃 / Successor', '沈腾/马丽/史彭元/萨日娜', '抓娃娃.png', '闫非/彭大魔', 7.5, 697432, '喜剧', 'tt30093951', '汉语普通话', 128, '', '中国大陆', '2024-07-19', '富商夫妇假装贫穷，对儿子进行全面监控式教育，在这个精心设计的\"贫困\"环境中，父子之间产生了一系列令人捧腹又感慨万千的故事。', '喜剧/2024/中国/沈腾/马丽/家庭/教育/夏天', 2024, '沈腾:1178869|马丽:1178867|史彭元:1389598|萨日娜:1033698', '闫非:1389599|彭大魔:1389600');
INSERT INTO `movie` (`movie_id`, `movie_name`, `movie_alias`, `actors`, `cover`, `directors`, `douban_score`, `douban_votes`, `type`, `imdb_id`, `languages`, `minutes`, `official_site`, `regions`, `release_date`, `description`, `tags`, `year`, `actor_ids`, `director_ids`) VALUES (36011561, '周处除三害', '九龙城寨之围城 / The Pig, the Snake and the Pigeon', '阮经天/袁富华/陈以文/李李仁/王净', '周处除三害.png', '黄精甫', 8.2, 843562, '剧情/动作/犯罪', 'tt26745314', '汉语普通话', 134, '', '中国台湾', '2024-03-22', '通缉犯陈桂林（阮经天）意外得知自己身患绝症时日无多，决定在死前消灭通缉名单上排在自己前面的两名罪犯，由此踏上了一段震撼人心的除恶之旅。', '台湾/犯罪/2024/动作/剧情/阮经天/黑色/震撼', 2024, '阮经天:1083020|袁富华:1389588|陈以文:1057638|李李仁:1389589', '黄精甫:1389590');
INSERT INTO `movie` (`movie_id`, `movie_name`, `movie_alias`, `actors`, `cover`, `directors`, `douban_score`, `douban_votes`, `type`, `imdb_id`, `languages`, `minutes`, `official_site`, `regions`, `release_date`, `description`, `tags`, `year`, `actor_ids`, `director_ids`) VALUES (36248601, '好东西', '好东西 / Her Story', '宋佳/钟楚曦/赵又廷/吴磊/连燊樁', '好东西.png', '邵艺辉', 9, 623145, '剧情/爱情/喜剧', 'tt30869021', '汉语普通话', 114, '', '中国大陆', '2024-11-15', '前调查记者王铁梅（宋佳）独自带女儿生活，与邻居小叶（钟楚曦）成为好友，两段真实而温暖的女性友谊在上海徐徐展开。', '剧情/女性/2024/中国/友情/都市/现实/感动', 2024, '宋佳:1062462|钟楚曦:1389622|赵又廷:1109706|吴磊:1286671', '邵艺辉:1389623');
